window.AUTH=window.AUTH||{};window.AUTH["22-179"]={"d":"22-179","id":"2022/22-179","n":"United States v. Hansen","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2023-01-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-179/252558/20230118184710475_22-179tsUnitedStates.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondent Helaman Hansen","date":"2023-02-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-179/255020/20230217090707118_22-179%20USA%20v%20Hansen%20Brief%20for%20Respondent.pdf","side":"res","n":83},{"k":"reply","label":"Reply of petitioner United States","date":"2023-03-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-179/259323/20230317133507306_22-179rbUnitedStates.pdf","side":"pet","n":50}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r49_jgkn.pdf","tr":true,"items":[{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"op":3,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"38","1":"26, 38"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"op":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Building Serv. Emps. Int’l Union v. Gazzam","cite":"339 U.S. 532","y":1950,"id":"scdb/1949-076","sc":1,"sum":"In a state whose public policy is that employers shall not coerce their employees' choice of a bargaining representative, a state court injunction against peaceful picketing by a labor union for the particular purpose of compelling an employer to sign a contract which would coerce his employees' choice of a bargaining representative does not violate the right of free speech guaranteed by the First and Fourteenth …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","2":"17, 18"}},{"t":"case","label":"Cox v. Louisiana","cite":"379 U.S. 559","y":1965,"id":"1964/49","sc":1,"sum":"The Court determined whether a conviction based on a Louisiana statute prohibiting picketing before a courthouse violated the defendant's rights to free speech and assembly under the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Davis v. Michigan Dep’t of the Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"DelRio-Mocci v. Connolly Props. Inc.","cite":"672 F.3d 241","y":2012,"url":"https://www.courtlistener.com/c/F.3d/672/241/","sum":"Construing Section 1324(a)(1)(A)(iv) to prohibit “an affirmative act that substantially encourages or induces an alien lacking lawful immigration status to come to, enter, or reside in the United States where the undocumented person otherwise might not have done so”.","sumSrc":"brief:0","by":{"0":"33","1":"20, 47"}},{"t":"case","label":"Elonis v. United States","cite":"575 U.S. 723","y":2015,"id":"2014/13-983","sc":1,"op":1,"ar":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"0":"28","2":"23"}},{"t":"case","label":"Ford v. State","cite":"262 P.3d 1123","y":2011,"court":"Nev.","url":"https://www.courtlistener.com/c/P.3d/262/1123/","sum":"Construing prohibition on soliciting prostitution not to reach “abstract advocacy”.","sumSrc":"brief:0","by":{"0":"32"}},{"t":"case","label":"Fox v. Washington","cite":"236 U.S. 273","y":1915,"id":"scdb/1914-215","sc":1,"sum":"Where the highest court of the State, in overruling a demurrer, affirmed that the Constitution of the United States guaranteed freedom of speech, but held the'statute on which the indictment was based valid in that respect and also that it was not bad for uncertainty, citing cases decided by this court as authority, this court may gather that rights under the Federal Constitution were relied on apart from the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Frohwerk v. United States","cite":"249 U.S. 204","y":1919,"id":"1900-1940/249us204","sc":1,"sum":"The Court held that the conviction of a defendant for publishing articles criticizing the US involvement in World War I under the Espionage Act of 1917 does not violate the publisher's free speech rights under the First Amendment.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Giboney v. Empire Storage & Ice Co.","cite":"336 U.S. 490","y":1949,"id":"scdb/1948-056","sc":1,"op":2,"ar":1,"sum":"The state law, as construed and applied in this case, does not violate the Federal Constitution, and the judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"10, 18, 39","2":"17, 18"}},{"t":"case","label":"Grant Bros. Constr. Co. v. United States","cite":"232 U.S. 647","y":1914,"id":"scdb/1913-204","sc":1,"sum":"An action by the United States to recover penalties under the Alien Contract Labor Law is civil and attended with the usual incidents of a civil action. United States v. Regan, ante, p. 37.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"sum":"That an acquittal of a charge of wilful attempt to evade, under § 146 (b), does not bar assessment and collection of the 50% addition prescribed by § 293 (b)..397 et seq. The doctrine of res judicata is inapplicable because of the difference in quantum of proof in civil and criminal cases; the acquittal was merely an adjudication that the proof was not sufficient to overcome all reasonable doubt of guilt. P. 397. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Hudson v. United States","cite":"522 U.S. 93","y":1997,"id":"1997/96-976","sc":1,"sum":"The Court held that the Double Jeopardy Clause does not apply to non-criminal penalties, even if the purpose of the penalty is to punish the offenders and deter future offenders. Since the first punishment handed down by the OCC - a Federal Banking Agency, not a court - was not a criminal punishment, the subsequent indictments were upheld.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"International Bhd. of Elec. Workers v. NLRB","cite":"341 U.S. 694","y":1951,"id":"scdb/1950-096","sc":1,"sum":"This finding and the order are sustained. See Labor Board v. Denver Building Trades Council, ante, p. 675.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 42","1":"40"}},{"t":"case","label":"International Bhd. of Teamsters v. Vogt, Inc.","cite":"354 U.S. 284","y":1957,"id":"1956/79","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"40, 41"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Lees v. United States","cite":"150 U.S. 476","y":1893,"id":"scdb/1893-058","sc":1,"op":1,"sum":"A district court of the United States has jurisdiction over an action to recover a penalty imposed for a violation of the act of February 26, 1885, '23 Stat. 332, c. 164, “to prohibit the importation and migration of foreigners and aliens under contract or agreement to perform labor in the United States, its Territories, and the District of Columbia.”","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5, 25, 43"}},{"t":"case","label":"Los Angeles Police Dep’t v. United Reporting Publ’g Corp.","cite":"528 U.S. 32","y":1999,"id":"1999/98-678","sc":1,"op":1,"sum":"The Court held that the amended statute was not an abridgment of anyone's right to engage in speech, commercial or otherwise, but simply a law regulating access to information in the hands of law enforcement agencies.","sumSrc":"Oyez","by":{"0":"17, 19","2":"21"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Members of the City Council v. Taxpayers for Vin- cent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"op":2,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20, 45","2":"11, 12"}},{"t":"case","label":"Milavetz, Gallop & Milavetz, P.A. v. United States","cite":"559 U.S. 229","y":2010,"id":"2009/08-1119","sc":1,"op":6,"sum":"The Court held that attorneys who provide bankruptcy assistance are debt relief agencies under the Bankruptcy Abuse Prevention and Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"New York v. Ferber","cite":"458 U.S. 747","y":1982,"id":"1981/81-55","sc":1,"sum":"In the Court's first examination of a statute specifically targeted against child pornography, it found that the state's interest in preventing sexual exploitation of minors was a compelling \"government objective of surpassing importance.\" The law was carefully drawn to protect children from the mental, physical, and sexual abuse associated with pornography while not violating the First Amendment.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Pittsburgh Press Co. v. Pittsburgh Comm’n on Human Relations","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"op":1,"ar":3,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":"42","1":"40","2":"18"}},{"t":"case","label":"Reves v. Ernst & Young","cite":"507 U.S. 170","y":1993,"id":"1992/91-886","sc":1,"op":1,"sum":"One must participate in the operation or management of the enterprise itself in order to be subject to §1962(c) liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"op":4,"ar":3,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"0":"28","1":"29, 31","2":"6"}},{"t":"case","label":"State v. Ferguson","cite":"264 P.3d 575","y":2011,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/264/575/","sum":"Construing aiding-and-abetting statute not to “forbid the mere advocacy of law violation,” and rejecting overbreadth challenge.","sumSrc":"brief:0","by":{"0":"32","1":"32"}},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"sum":"The Supreme Court held that making false statements to an FBI agent who may or may not testify at trial is not sufficient to support a conviction for obstruction of justice. Aguilar’s conviction for disclosing a wiretap was proper, however, because the statute does not require that the wiretap is currently in force. The First Amendment did not require excluding expired wiretaps from the statute either.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Alvarez","cite":"567 U.S. 709","y":2012,"id":"2011/11-210","sc":1,"op":1,"ar":1,"sum":"The Court found that the Stolen Valor Act violated the First Amendment.","sumSrc":"Oyez","by":{"0":"47, 48","1":"34"}},{"t":"case","label":"United States v. Castillo-Felix","cite":"539 F.2d 9","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/539/9/","op":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Evans","cite":"333 U.S. 483","y":1948,"id":"scdb/1947-057","sc":1,"sum":"1. Section 8 of the Immigration Act of 1917 does not make it a punishable offense to conceal or harbor aliens not entitled to enter or reside in the United States, in view of the ambiguity in the statute as to the scope of the offense and as to the penalty which Congress intended to prescribe,","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"United States v. Fujii","cite":"301 F.3d 535","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/301/535/","by":{"0":"37"}},{"t":"case","label":"United States v. Garcia-Paulin","cite":"627 F.3d 127","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/127/","by":{"0":"39","2":"13"}},{"t":"case","label":"United States v. He","cite":"245 F.3d 954","y":2001,"url":"https://www.courtlistener.com/c/F.3d/245/954/","by":{"0":"28, 37"}},{"t":"case","label":"United States v. Henderson","cite":"857 F. Supp. 2d 191","y":2012,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/857/191/","ar":2,"by":{"0":"46","2":"11"}},{"t":"case","label":"United States v. Hoy","cite":"330 U.S. 724","y":1947,"id":"scdb/1946-081","sc":1,"op":2,"sum":"Explaining that the 1917 Act barred “contract laborers, defned as persons induced or encouraged to come to this country by offers or promises of employment” (emphasis added).","sumSrc":"opinion","by":{"0":"26","2":"4"}},{"t":"case","label":"United States v. Kalu","cite":"791 F.3d 1194","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/1194/","op":1,"by":{"0":"27, 37"}},{"t":"case","label":"United States v. Martinez","cite":"900 F.3d 721","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/721/","by":{"0":"36"}},{"t":"case","label":"United States v. Ndiaye","cite":"434 F.3d 1270","y":2006,"url":"https://www.courtlistener.com/c/F.3d/434/1270/","by":{"0":"36"}},{"t":"case","label":"United States v. Okatan","cite":"728 F.3d 111","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/111/","op":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Oloyede","cite":"982 F.2d 133","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/982/133/","by":{"0":"36"}},{"t":"case","label":"United States v. Raines","cite":"362 U.S. 17","y":1960,"id":"1959/64","sc":1,"sum":"Under authority of R. S. § 2004, as amended by the Civil Rights Act of 1957, the Attorney General bronght this civil action on behalf of the United States in a Federal District Court to enjoin certain public officials of the State of Georgia from discriminating against Negro citizens who desired to register to vote in elections in Georgia. 'The District Court dismissed the complaint on the ground that subsection …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Sineneng-Smith: 910 F.3d 461 (9th Cir. 2018), vacated and remanded","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"op":8,"ar":4,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"0":"10, 11, 28, 32, 42, 45, 47","1":"46"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"op":7,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"41, 49","1":"18, 20, 21, 24, 35, 39, 41","2":"14, 17, 20"}},{"t":"case","label":"United States v. Tracy","cite":"456 Fed. Appx. 267","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./456/267/","op":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"op":10,"ar":6,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"15, 17, 19, 20, 25, 27-30, 32, 40-42, 44, 45, 48, 49","1":"10, 14, 18, 19, 31","2":"3, 11-14, 16, 18, 19, 21, 23"}},{"t":"case","label":"United States v. Yoshida","cite":"303 F.3d 1145","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/303/1145/","op":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Zayas-Morales","cite":"685 F.2d 1272","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/685/1272/","by":{"0":"28"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"op":2,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"0":"19, 20, 40, 46"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"0":"18, 36"}},{"t":"const","label":"Amendment I, Section 3","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"7","1":"4"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(b)(1)","(a)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"5, 6, 7","1":"17, 3","2":"4"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)"],"by":{"0":"34"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(a)"],"stext":{"head":"§1253. Penalties related to removal","paras":[[0,"(a) Penalty for failure to depart"],[0,"(1) In general"],[1,"Any alien against whom a final order of removal is outstanding by reason of being a member of any of the classes described in section 1227(a) of this title, who—"],[2,"(A) willfully fails or refuses to depart from the United States within a period of 90 days from the date of the final order of removal under administrative processes, or if judicial review is had, then from the date of the final order of the court,"],[2,"(B) willfully fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure,"],[2,"(C) connives or conspires, or takes any other action, designed to prevent or hamper or with the purpose of preventing or hampering the alien's departure pursuant to such, or"],[2,"(D) willfully fails or refuses to present himself or herself for removal at the time and place required by the Attorney General pursuant to such order,"],[1,"shall be fined under title 18, or imprisoned not more than four years (or 10 years if the alien is a member of any of the classes described in paragraph (1)(E), (2), (3), or (4) of section 1227(a) of this title), or both."],[0,"(2) Exception"],[1,"It is not a violation of paragraph (1) to take any proper steps for the purpose of securing cancellation of or exemption from such order of removal or for the purpose of securing the alien's release from incarceration or custody."],[0,"(3) Suspension"],[1,"The court may for good cause suspend the sentence of an alien under this subsection and order the alien's release under such conditions as the court may prescribe. In determining whether good cause has been shown to justify releasing the alien, the court shall take into account such factors as—"],[2,"(A) the age, health, and period of detention of the alien;"],[2,"(B) the effect of the alien's release upon the national security and public peace or safety;"],[2,"(C) the likelihood of the alien's resuming or following a course of conduct which made or would make the alien deportable;"],[2,"(D) the character of the efforts made by such alien himself and by representatives of the country or countries to which the alien's removal is directed to expedite the alien's departure from the United States;"],[2,"(E) the reason for the inability of the Government of the United States to secure passports, other travel documents, or removal facilities from the country or countries to which the alien has been ordered removed; and"],[2,"(F) the eligibility of the alien for discretionary relief under the immigration laws."],[0,"(b) Willful failure to comply with terms of release under supervision"],[0,"An alien who shall willfully fail to comply with regulations or requirements issued pursuant to section 1231(a)(3) of this title or knowingly give false information in response to an inquiry under such section shall be fined not more than $1,000 or imprisoned for not more than one year, or both."],[0,"(c) Penalties relating to vessels and aircraft"],[0,"(1) Civil penalties"],[0,"(A) Failure to carry out certain orders"],[2,"If the Attorney General is satisfied that a person has violated subsection (d) or (e) of section 1231 of this title, the person shall pay to the Commissioner the sum of $2,000 for each violation."],[0,"(B) Failure to remove alien stowaways"],[2,"If the Attorney General is satisfied that a person has failed to remove an alien stowaway as required under section 1231(d)(2) of this title, the person shall pay to the Commissioner the sum of $5,000 for each alien stowaway not removed."],[0,"(C) No compromise"],[2,"The Attorney General may not compromise the amount of such penalty under this paragraph."],[0,"(2) Clearing vessels and aircraft"],[0,"(A) Clearance before decision on liability"],[2,"A vessel or aircraft may be granted clearance before a decision on liability is made under paragraph (1) only if a bond approved by the Attorney General or an amount sufficient to pay the civil penalty is deposited with the Commissioner."],[0,"(B) Prohibition on clearance while penalty unpaid"],[2,"A vessel or aircraft may not be granted clearance if a civil penalty imposed under paragraph (1) is not paid."],[0,"(d) Discontinuing granting visas to nationals of country denying or delaying accepting alien"],[0,"On being notified by the Attorney General that the government of a foreign country denies or unreasonably delays accepting an alien who is a citizen, subject, national, or resident of that country after the Attorney General asks whether the government will accept the alien under this section, the Secretary of State shall order consular officers in that foreign country to discontinue granting immigrant visas or nonimmigrant visas, or both, to citizens, subjects, nationals, and residents of that country until the Attorney General notifies the Secretary that the country has accepted the alien."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1253?type=usc&year=mostrecent&link-type=html"},"head":"§1253. Penalties related to removal","tname":"Aliens and Nationality","by":{"0":"38","2":"20"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(1952)","(a)","(a)(1)(1982)","(a)(1)(A)","(a)(1)(A)(i)","(a)(1)(A)(iv)","(a)(1)(A)(v)(II)","(a)(1)(B)","(a)(1)(B)(i)","(a)(1)(B)(ii)","(a)(4)(1952)","(a)(1)(A)(ii)","(a)(1)(A)(iii)","(a)(4)(1982)"],"stext":{"head":"§1324. Bringing in and harboring certain aliens","paras":[[0,"(a) Criminal penalties"],[0,"(1)(A) Any person who—"],[1,"(i) knowing that a person is an alien, brings to or attempts to bring to the United States in any manner whatsoever such person at a place other than a designated port of entry or place other than as designated by the Commissioner, regardless of whether such alien has received prior official authorization to come to, enter, or reside in the United States and regardless of any future official action which may be taken with respect to such alien;"],[1,"(ii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, transports, or moves or attempts to transport or move such alien within the United States by means of transportation or otherwise, in furtherance of such violation of law;"],[1,"(iii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, conceals, harbors, or shields from detection, or attempts to conceal, harbor, or shield from detection, such alien in any place, including any building or any means of transportation;"],[1,"(iv) encourages or induces an alien to come to, enter, or reside in the United States, knowing or in reckless disregard of the fact that such coming to, entry, or residence is or will be in violation of law; or"],[1,"(v)(I) engages in any conspiracy to commit any of the preceding acts, or"],[1,"(II) aids or abets the commission of any of the preceding acts,"],[0,"shall be punished as provided in subparagraph (B)."],[0,"(B) A person who violates subparagraph (A) shall, for each alien in respect to whom such a violation occurs—"],[1,"(i) in the case of a violation of subparagraph (A)(i) or (v)(I) or in the case of a violation of subparagraph (A)(ii), (iii), or (iv) in which the offense was done for the purpose of commercial advantage or private financial gain, be fined under title 18, imprisoned not more than 10 years, or both;"],[1,"(ii) in the case of a violation of subparagraph (A)(ii), (iii), (iv), or (v)(II), be fined under title 18, imprisoned not more than 5 years, or both;"],[1,"(iii) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) during and in relation to which the person causes serious bodily injury (as defined in section 1365 of title 18) to, or places in jeopardy the life of, any person, be fined under title 18, imprisoned not more than 20 years, or both; and"],[1,"(iv) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) resulting in the death of any person, be punished by death or imprisoned for any term of years or for life, fined under title 18, or both."],[0,"(C) It is not a violation of clauses 1 (ii) or (iii) of subparagraph (A), or of clause (iv) of subparagraph (A) except where a person encourages or induces an alien to come to or enter the United States, for a religious denomination having a bona fide nonprofit, religious organization in the United States, or the agents or officers of such denomination or organization, to encourage, invite, call, allow, or enable an alien who is present in the United States to perform the vocation of a minister or missionary for the denomination or organization in the United States as a volunteer who is not compensated as an employee, notwithstanding the provision of room, board, travel, medical assistance, and other basic living expenses, provided the minister or missionary has been a member of the denomination for at least one year."],[0,"(2) Any person who, knowing or in reckless disregard of the fact that an alien has not received prior official authorization to come to, enter, or reside in the United States, brings to or attempts to bring to the United States in any manner whatsoever, such alien, regardless of any official action which may later be taken with respect to such alien shall, for each alien in respect to whom a violation of this paragraph occurs—"],[1,"(A) be fined in accordance with title 18 or imprisoned not more than one year, or both; or"],[1,"(B) in the case of—"],[2,"(i) an offense committed with the intent or with reason to believe that the alien unlawfully brought into the United States will commit an offense against the United States or any State punishable by imprisonment for more than 1 year,"],[2,"(ii) an offense done for the purpose of commercial advantage or private financial gain, or"],[2,"(iii) an offense in which the alien is not upon arrival immediately brought and presented to an appropriate immigration officer at a designated port of entry,"],[1,"be fined under title 18 and shall be imprisoned, in the case of a first or second violation of subparagraph (B)(iii), not more than 10 years, in the case of a first or second violation of subparagraph (B)(i) or (B)(ii), not less than 3 nor more than 10 years, and for any other violation, not less than 5 nor more than 15 years."],[0,"(3)(A) Any person who, during any 12-month period, knowingly hires for employment at least 10 individuals with actual knowledge that the individuals are aliens described in subparagraph (B) shall be fined under title 18 or imprisoned for not more than 5 years, or both."],[0,"(B) An alien described in this subparagraph is an alien who—"],[1,"(i) is an unauthorized alien (as defined in section 1324a(h)(3) of this title), and"],[1,"(ii) has been brought into the United States in violation of this subsection."],[0,"(4) In the case of a person who has brought aliens into the United States in violation of this subsection, the sentence otherwise provided for may be increased by up to 10 years if—"],[1,"(A) the offense was part of an ongoing commercial organization or enterprise;"],[1,"(B) aliens were transported in groups of 10 or more; and"],[1,"(C)(i) aliens were transported in a manner that endangered their lives; or"],[1,"(ii) the aliens presented a life-threatening health risk to people in the United States."],[0,"(b) Seizure and forfeiture"],[0,"(1) In general"],[1,"Any conveyance, including any vessel, vehicle, or aircraft, that has been or is being used in the commission of a violation of subsection (a), the gross proceeds of such violation, and any property traceable to such conveyance or proceeds, shall be seized and subject to forfeiture."],[0,"(2) Applicable procedures"],[1,"Seizures and forfeitures under this subsection shall be governed by the provisions of chapter 46 of title 18 relating to civil forfeitures, including section 981(d) of such title, except that such duties as are imposed upon the Secretary of the Treasury under the customs laws described in that section shall be performed by such officers, agents, and other persons as may be designated for that purpose by the Attorney General."],[0,"(3) Prima facie evidence in determinations of violations"],[1,"In determining whether a violation of subsection (a) has occurred, any of the following shall be prima facie evidence that an alien involved in the alleged violation had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law:"],[2,"(A) Records of any judicial or administrative proceeding in which that alien's status was an issue and in which it was determined that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(B) Official records of the Service or of the Department of State showing that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(C) Testimony, by an immigration officer having personal knowledge of the facts concerning that alien's status, that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[0,"(c) Authority to arrest"],[0,"No officer or person shall have authority to make any arrests for a violation of any provision of this section except officers and employees of the Service designated by the Attorney General, either individually or as a member of a class, and all other officers whose duty it is to enforce criminal laws."],[0,"(d) Admissibility of videotaped witness testimony"],[0,"Notwithstanding any provision of the Federal Rules of Evidence, the videotaped (or otherwise audiovisually preserved) deposition of a witness to a violation of subsection (a) who has been deported or otherwise expelled from the United States, or is otherwise unable to testify, may be admitted into evidence in an action brought for that violation if the witness was available for cross examination and the deposition otherwise complies with the Federal Rules of Evidence."],[0,"(e) Outreach program"],[0,"The Secretary of Homeland Security, in consultation with the Attorney General and the Secretary of State, as appropriate, shall develop and implement an outreach program to educate the public in the United States and abroad about the penalties for bringing in and harboring aliens in violation of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1324?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":5,"head":"§1324. Bringing in and harboring certain aliens","tname":"Aliens and Nationality","by":{"0":"5, 26, 6, 28, 28, 6, 6, 6, 6, 6, 6, 6, 6, 6","1":"1, 3, 4, 6, 7, 20, 22, 23, 27, 28, 30, 32","2":"8, 8, 9, 13, 8, 8, 13, 1, 2, 4-17, 20-23, 9, 21, 22, 7"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","subs":["(a)"],"stext":{"head":"§1325. Improper entry by alien","paras":[[0,"(a) Improper time or place; avoidance of examination or inspection; misrepresentation and concealment of facts"],[0,"Any alien who (1) enters or attempts to enter the United States at any time or place other than as designated by immigration officers, or (2) eludes examination or inspection by immigration officers, or (3) attempts to enter or obtains entry to the United States by a willfully false or misleading representation or the willful concealment of a material fact, shall, for the first commission of any such offense, be fined under title 18 or imprisoned not more than 6 months, or both, and, for a subsequent commission of any such offense, be fined under title 18, or imprisoned not more than 2 years, or both."],[0,"(b) Improper time or place; civil penalties"],[0,"Any alien who is apprehended while entering (or attempting to enter) the United States at a time or place other than as designated by immigration officers shall be subject to a civil penalty of—"],[1,"(1) at least $50 and not more than $250 for each such entry (or attempted entry); or"],[1,"(2) twice the amount specified in paragraph (1) in the case of an alien who has been previously subject to a civil penalty under this subsection."],[0,"Civil penalties under this subsection are in addition to, and not in lieu of, any criminal or other civil penalties that may be imposed."],[0,"(c) Marriage fraud"],[0,"Any individual who knowingly enters into a marriage for the purpose of evading any provision of the immigration laws shall be imprisoned for not more than 5 years, or fined not more than $250,000, or both."],[0,"(d) Immigration-related entrepreneurship fraud"],[0,"Any individual who knowingly establishes a commercial enterprise for the purpose of evading any provision of the immigration laws shall be imprisoned for not more than 5 years, fined in accordance with title 18, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1325?type=usc&year=mostrecent&link-type=html"},"head":"§1325. Improper entry by alien","tname":"Aliens and Nationality","by":{"0":"38","1":"38"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(a)"],"by":{"0":"38"}},{"t":"usc","label":"8 U.S.C. § 1431","url":"https://www.law.cornell.edu/uscode/text/8/1431","by":{"0":"7"}},{"t":"usc","label":"8 U.S.C. § 1433","url":"https://www.law.cornell.edu/uscode/text/8/1433","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3359","by":{"0":"6","1":"3"}},{"t":"usc","label":"18 U.S.C. § 2421","url":"https://www.law.cornell.edu/uscode/text/18/2421","by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 2422","url":"https://www.law.cornell.edu/uscode/text/18/2422","subs":["(a)","(b)"],"by":{"0":"23, 23"}},{"t":"usc","label":"8 U.S.C. § 142","url":"https://www.law.cornell.edu/uscode/text/8/142","subs":["(1946)"],"by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 78ff","url":"https://www.law.cornell.edu/uscode/text/15/78ff","subs":["(a)"],"by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","subs":["(a)"],"stext":{"head":"§2. Principals","paras":[[0,"(a) Whoever commits an offense against the United States or aids, abets, counsels, commands, induces or procures its commission, is punishable as a principal."],[0,"(b) Whoever willfully causes an act to be done which if directly performed by him or another would be an offense against the United States, is punishable as a principal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2. Principals","tname":"Crimes and Criminal Procedure","by":{"0":"47","1":"5, 22, 23, 28","2":"6"}},{"t":"usc","label":"18 U.S.C. § 373","url":"https://www.law.cornell.edu/uscode/text/18/373","subs":["(a)"],"stext":{"head":"§373. Solicitation to commit a crime of violence","paras":[[0,"(a) Whoever, with intent that another person engage in conduct constituting a felony that has as an element the use, attempted use, or threatened use of physical force against property or against the person of another in violation of the laws of the United States, and under circumstances strongly corroborative of that intent, solicits, commands, induces, or otherwise endeavors to persuade such other person to engage in such conduct, shall be imprisoned not more than one-half the maximum term of imprisonment or (notwithstanding section 3571) fined not more than one-half of the maximum fine prescribed for the punishment of the crime solicited, or both; or if the crime solicited is punishable by life imprisonment or death, shall be imprisoned for not more than twenty years."],[0,"(b) It is an affirmative defense to a prosecution under this section that, under circumstances manifesting a voluntary and complete renunciation of his criminal intent, the defendant prevented the commission of the crime solicited. A renunciation is not \"voluntary and complete\" if it is motivated in whole or in part by a decision to postpone the commission of the crime until another time or to substitute another victim or another but similar objective. If the defendant raises the affirmative defense at trial, the defendant has the burden of proving the defense by a preponderance of the evidence."],[0,"(c) It is not a defense to a prosecution under this section that the person solicited could not be convicted of the crime because he lacked the state of mind required for its commission, because he was incompetent or irresponsible, or because he is immune from prosecution or is not subject to prosecution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/373?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§373. Solicitation to commit a crime of violence","tname":"Crimes and Criminal Procedure","by":{"0":"47","1":"5, 27, 29","2":"9"}},{"t":"usc","label":"18 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/18/704","subs":["(b)(2006)","(c)(2006)"],"stext":{"head":"§704. Military medals or decorations","paras":[[0,"(a) In General.—Whoever knowingly purchases, attempts to purchase, solicits for purchase, mails, ships, imports, exports, produces blank certificates of receipt for, manufactures, sells, attempts to sell, advertises for sale, trades, barters, or exchanges for anything of value any decoration or medal authorized by Congress for the armed forces of the United States, or any of the service medals or badges awarded to the members of such forces, or the ribbon, button, or rosette of any such badge, decoration or medal, or any colorable imitation thereof, except when authorized under regulations made pursuant to law, shall be fined under this title or imprisoned not more than six months, or both."],[0,"(b) Fraudulent Representations About Receipt of Military Decorations or Medals.—Whoever, with intent to obtain money, property, or other tangible benefit, fraudulently holds oneself out to be a recipient of a decoration or medal described in subsection (c)(2) or (d) shall be fined under this title, imprisoned not more than one year, or both."],[0,"(c) Enhanced Penalty for Offenses Involving Congressional Medal of Honor.—"],[1,"(1) In general.—If a decoration or medal involved in an offense under subsection (a) is a Congressional Medal of Honor, in lieu of the punishment provided in that subsection, the offender shall be fined under this title, imprisoned not more than 1 year, or both."],[1,"(2) Congressional medal of honor defined.—In this subsection, the term \"Congressional Medal of Honor\" means—"],[2,"(A) a medal of honor awarded under section 7271, 8291, or 9271 of title 10 or section 491 1 of title 14;"],[2,"(B) a duplicate medal of honor issued under section 7284, 8306, or 9284 of title 10 or section 504 1 of title 14; or"],[2,"(C) a replacement of a medal of honor provided under section 7277, 8303, or 9277 of title 10 or section 501 1 of title 14."],[0,"(d) Enhanced Penalty for Offenses Involving Certain Other Medals.—"],[1,"(1) In general.—If a decoration or medal involved in an offense described in subsection (a) is a distinguished-service cross awarded under section 7272 of title 10, a Navy cross awarded under section 8292 of title 10, an Air Force cross awarded under section 9272 of title 10, a silver star awarded under section 7276, 8294, or 9276 of title 10, a Purple Heart awarded under section 1129 of title 10, a combat badge, or any replacement or duplicate medal for such medal as authorized by law, in lieu of the punishment provided in the applicable subsection, the offender shall be fined under this title, imprisoned not more than 1 year, or both."],[1,"(2) Combat badge defined.—In this subsection, the term \"combat badge\" means a Combat Infantryman's Badge, Combat Action Badge, Combat Medical Badge, Combat Action Ribbon, or Combat Action Medal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/704?type=usc&year=mostrecent&link-type=html"},"head":"§704. Military medals or decorations","tname":"Crimes and Criminal Procedure","by":{"0":"47, 47","1":"34"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","stext":{"head":"§1341. Frauds and swindles","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, or to sell, dispose of, loan, exchange, alter, give away, distribute, supply, or furnish or procure for unlawful use any counterfeit or spurious coin, obligation, security, or other article, or anything represented to be or intimated or held out to be such counterfeit or spurious article, for the purpose of executing such scheme or artifice or attempting so to do, places in any post office or authorized depository for mail matter, any matter or thing whatever to be sent or delivered by the Postal Service, or deposits or causes to be deposited any matter or thing whatever to be sent or delivered by any private or commercial interstate carrier, or takes or receives therefrom, any such matter or thing, or knowingly causes to be delivered by mail or such carrier according to the direction thereon, or at the place at which it is directed to be delivered by the person to whom it is addressed, any such matter or thing, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1341?type=usc&year=mostrecent&link-type=html"},"head":"§1341. Frauds and swindles","tname":"Crimes and Criminal Procedure","by":{"0":"4, 9","1":"5","2":"13"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","stext":{"head":"§1343. Fraud by wire, radio, or television","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, transmits or causes to be transmitted by means of wire, radio, or television communication in interstate or foreign commerce, any writings, signs, signals, pictures, or sounds for the purpose of executing such scheme or artifice, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1343?type=usc&year=mostrecent&link-type=html"},"head":"§1343. Fraud by wire, radio, or television","tname":"Crimes and Criminal Procedure","by":{"0":"4, 9","1":"5","2":"13"}},{"t":"usc","label":"18 U.S.C. § 2252A","url":"https://www.law.cornell.edu/uscode/text/18/2252A","subs":["(a)(3)(B)(2006)"],"by":{"0":"29"}},{"t":"usc","label":"26 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/26/7201","by":{"0":"44"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(b)(4)"],"by":{"0":"42"}},{"t":"case","label":"Abrams v. United States","cite":"250 U.S. 616","y":1919,"id":"1900-1940/250us616","sc":1,"sum":"The Court found that the Espionage Act did not violate the First Amendment if the speech incited resistance to war.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Americans for Prosperity Foundation v. Bonta","cite":"141 S. Ct. 2373","y":2021,"id":"2020/19-251","sc":1,"op":3,"sum":"The Ninth Circuit’s judgment, which vacated the District Court’s injunction of California’s compelled disclosure of Schedule Bs as not narrowly tailored to the State’s interest in investigating charitable misconduct, is reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22","2":"12"}},{"t":"case","label":"Ashcroft v. Free Speech Coalition","cite":"535 U.S. 234","y":2002,"id":"2001/00-795","sc":1,"op":1,"sum":"The Court held that the two prohibitions described above are overbroad and unconstitutional. The Court found the CPPA to be inconsistent with Miller insofar as the CPPA cannot be read to prohibit obscenity, because it lacks the required link between its prohibitions and the affront to community standards prohibited by the obscenity definition.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Bigelow v. Virginia","cite":"421 U.S. 809","y":1975,"id":"1974/73-1309","sc":1,"sum":"The Court held that the Virginia law infringed upon Bigelow's First Amendment rights and violated the Constitution. Citing prior holdings such as New York Times v. Sullivan (1964), Justice Blackmun denied the Supreme Court of Virginia's ruling that commercial speech is not afforded First Amendment protection.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Board of Trustees of State University of New York v. Fox","cite":"492 U.S. 469","y":1989,"id":"1988/87-2013","sc":1,"sum":"Resolution 66-156 of the State University of New York (SUNY) prohibits private commercial enterprises from operating in SUNY facilities. After the resolution was applied by campus police to bar American Future Systems, Inc. (AFS), from demonstrating and selling its housewares at a party hosted in a student dormitory, respondent Fox and other students sued for a declaratory judgment that such action violated the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Bolmer v. Connolly Properties Inc.","cite":"568 U.S. 821","y":2012,"url":"https://supreme.justia.com/cases/federal/us/568/821/","sc":1,"by":{"1":"20, 47"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Brown v. Entertainment Media","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"1":"41, 43"}},{"t":"case","label":"Chaplinsky v. New Hampshire","cite":"315 U.S. 568","y":1942,"id":"1940-1955/315us568","sc":1,"sum":"The Court ruled that some words, such as obscenities, are not protected under the First Amendment.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"sum":"A duty to disclose information arises if there is a relationship of trust and confidence between parties to the transaction. Chiarella had no such duty. He was not a corporate insider in the acquiring corporation and he did not receive confidential information from the target company.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Coates v. City of Cincinnati","cite":"402 U.S. 611","y":1971,"id":"1970/117","sc":1,"sum":"Cincinnati, Ohio, ordinance making it a criminal offense for \"three or more persons to assemble... on any of the sidewalks... and there conduct themselves in a manner annoying to persons passing by...,\" which has not been narrowed by any construction of the Ohio Supreme Court, held violative on its face of the due process standard of vagueness and the constitutional right of free assembly and association. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Edwards v. Prime, Inc.","cite":"602 F.3d 1276","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/602/1276/","op":2,"by":{"1":"20"}},{"t":"case","label":"Ford v. State","cite":"127 Nev. 608","y":2011,"court":"Nev.","url":"https://www.courtlistener.com/c/Nev./127/608/","by":{"1":"32"}},{"t":"case","label":"Gooding v. Wilson","cite":"405 U.S. 518","y":1972,"id":"1971/70-26","sc":1,"sum":"The Supreme Court held that the Georgia statute was unconstitutional. With Justice William J. Brennan writing for the majority, the Court reasoned that the statute was unconstitutionally vague and overbroad. Quoting Speiser v. Randall , the Court noted that \"the separation of legitimate from illegitimate speech calls for more sensitive tools than (Georgia) has supplied.\" Chief Justice Warren E. Burger dissented.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"30","2":"7"}},{"t":"case","label":"Keyishian v. Board of Regents of University of State of New York","cite":"385 U.S. 589","y":1967,"id":"1966/105","sc":1,"sum":"The Court held that the provisions of the New York plan were defined in such uncertain terms that they infringed upon the constitutional rights of public servants.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Murdock v. Pennsylvania","cite":"319 U.S. 105","y":1943,"id":"1940-1955/319us105","sc":1,"sum":"The Court held that it was unconstitutional for a state to require solicitors to obtain a license that amounted to a tax on religious activities.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"National Institute of Family & Life Advocates v. Becerra","cite":"138 S. Ct. 2361","y":2018,"id":"2017/16-1140","sc":1,"op":3,"sum":"The Court decided that pro-life pregnancy center petitioners were likely to succeed on their claim that the California Reproductive Freedom, Accountability, Comprehensive Care, and Transparency Act violated the First Amendment.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"New York Times v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"ar":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"1":"20, 21","2":"23"}},{"t":"case","label":"Rewis v. United States","cite":"401 U.S. 808","y":1971,"id":"1970/5342","sc":1,"sum":"Conducting a gambling operation frequented by out-of-state bettors does not, without more, constitute a.violation of the Travel Act. Pp. 811-814. 418 F. 2d 1218, reversed. MARSHALL, J.,.delivered the opinion of the *Court, in which all members joined except WHITE, J., who took no part in the decision of the case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Rex v. Higgins","cite":"102 Eng. Rep. 269","y":1801,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./102/269/","by":{"1":"39"}},{"t":"case","label":"Shuttlesworth v. City of Birmingham","cite":"382 U.S. 87","y":1965,"id":"1965/5","sc":1,"sum":"Writing for a unanimous court, Justice Potter Stewart held that while both portions of the statute were facially constitutional, the trial court unconstitutionally applied the “obstructing free passage” portion of the ordinance.","sumSrc":"Oyez","by":{"1":"45, 48"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"sum":"To obtain a § 5861(d) conviction, the Government should have been required to prove beyond a reasonable doubt that Staples knew that his rifle had the characteristics that brought it within the statutory definition of a machinegun.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"State v. Avery","cite":"7 Conn. 266","y":1828,"court":"Conn.","url":"https://www.courtlistener.com/c/Conn./7/266/","by":{"1":"39"}},{"t":"case","label":"State v. Melchert-Dinkel","cite":"844 N.W.2d 13","y":2014,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/844/13/","ar":1,"by":{"1":"43, 44"}},{"t":"case","label":"State v. Sullivan","cite":"84 S.W. 105","y":1904,"court":"Mo. App.","url":"https://www.courtlistener.com/c/S.W./84/105/","by":{"1":"39"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Virginia State Board of Pharmacy v. Virginia Citizens Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Watts v. United States","cite":"394 U.S. 705","y":1969,"id":"1968/1107_misc","sc":1,"sum":"The Court concluded, without hearing arguments, that Watts' statement was \"political hyperbole\". The Court noted, \"The language of the political arena… is often vituperative, abusive, and inexact.\" Thus, considering the \"context, and regarding the expressly conditional nature of the statement and the reaction of the listeners,\" the Court ruled that Watts' statement was not a true threat.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Whitney v. California","cite":"274 U.S. 357","y":1927,"id":"1900-1940/274us357","sc":1,"sum":"The Court held that despite the First Amendment, a state can use its police power to punish speech that undermines the public welfare by inciting criminal activity, disturbing the peace, or advocating the violent overthrow of the government.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Yates v. United States","cite":"354 U.S. 298","y":1957,"id":"1956/6","sc":1,"sum":"The Court held that willfully and knowingly conspiring to teach and advocate the overthrow of the United States government as an abstract principle was not a violation of the Smith Act.","sumSrc":"Oyez","by":{"1":"45, 46"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"1, 9","2":"1, 2, 9, 11-14, 16-22"}},{"t":"reg","label":"8 C.F.R. § 204.11","url":"https://www.ecfr.gov/current/title-8/section-204.11","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)"],"by":{"1":"17"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","by":{"1":"17"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(c)(2)"],"by":{"1":"17"}},{"t":"usc","label":"8 U.S.C. § 1324a","url":"https://www.law.cornell.edu/uscode/text/8/1324a","by":{"1":"5"}},{"t":"usc","label":"8 U.S.C. § 1324c","url":"https://www.law.cornell.edu/uscode/text/8/1324c","by":{"1":"5"}},{"t":"usc","label":"8 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/8/1327","by":{"1":"5"}},{"t":"usc","label":"8 U.S.C. § 1328","url":"https://www.law.cornell.edu/uscode/text/8/1328","by":{"1":"5"}},{"t":"usc","label":"8 U.S.C. § 274","url":"https://www.law.cornell.edu/uscode/text/8/274","subs":["(a)(4)"],"by":{"1":"3"}},{"t":"usc","label":"10 U.S.C. § 882","url":"https://www.law.cornell.edu/uscode/text/10/882","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 177","url":"https://www.law.cornell.edu/uscode/text/18/177","subs":["(a)(2)"],"by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 229D","url":"https://www.law.cornell.edu/uscode/text/18/229D","subs":["(2)"],"by":{"1":"28"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"5"}},{"t":"usc","label":"18 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/18/1505","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 1543","url":"https://www.law.cornell.edu/uscode/text/18/1543","by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 1544","url":"https://www.law.cornell.edu/uscode/text/18/1544","by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 1546","url":"https://www.law.cornell.edu/uscode/text/18/1546","by":{"1":"4, 23"}},{"t":"usc","label":"18 U.S.C. § 1716","url":"https://www.law.cornell.edu/uscode/text/18/1716","subs":["(h)"],"by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 2192","url":"https://www.law.cornell.edu/uscode/text/18/2192","by":{"1":"27"}},{"t":"law","label":"Pub. L. No. 98-473","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"1":"20"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"sum":"The Court held that a Ku Klux Klan's First Amendment rights were violated by an Ohio criminal syndicalism law.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"op":2,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10, 12"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"op":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Farmer v. Brennan","cite":"511 U.S. 825","y":1994,"id":"1993/92-7247","sc":1,"sum":"The Supreme Court held that prison officials may be liable if they showed “deliberate indifference” to a substantial risk of serious harm when the official was subjectively aware of the risk and disregarded it. The Court remanded the case for further consideration of whether prison officials were aware of the risk to Farmer.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","by":{"2":"19"}},{"t":"case","label":"Metro-Goldwyn-Mayer Studios Inc. v. Grokster, Ltd.","cite":"545 U.S. 9130","y":2005,"url":"https://supreme.justia.com/cases/federal/us/545/9130/","sc":1,"by":{"2":"19"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Ruan v. United States","cite":"142 S. Ct. 2370","y":2022,"id":"2021/20-1410","sc":1,"op":1,"sum":"For the crime of prescribing controlled substances outside the usual course of professional practice in violation of 21 U. S. C. §841, the mens rea “knowingly or intentionally” applies to the statute’s “except as authorized” clause.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Rumsfeld v. FAIR, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"op":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"United States v. Costello","cite":"666 F.3d 1040","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/666/1040/","by":{"2":"13"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Voisine v. United States","cite":"579 U.S. 686","y":2016,"id":"2015/14-10154","sc":1,"sum":"The Court held that a reckless domestic violence assault qualifies as misdemeanor crime of domestic violence for the purpose of prohibiting firearm possession.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/18/1325","subs":["(a)"],"by":{"2":"20"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(b)"],"by":{"2":"19"}}]};